const s = wb.getWorksheet('Sheet1');
const src = s.getRange('B3:B22').getValues().map(r => String(r[0]));
const target = s.getRange('H3:H22').getValues().map(r => String(r[0]));
const out = src.map(t => t.split(',').map(p => p.trim()).flatMap(p => {
  const m = p.match(/^([A-Za-z]+)(\d+)-([A-Za-z]+)(\d+)$/);
  if (!m) return [p];
  const res = [];
  for (let i = Number(m[2]); i <= Number(m[4]); i++) res.push(m[1] + i);
  return res;
}).join(', '));
const diffs = out.map((v, i) => v === target[i] ? null : { row: i + 3, v, h: target[i] }).filter(Boolean);
